export type OneOnOneCallProps = Record<string, any>;

const OneOnOneCall: React.FC<OneOnOneCallProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 8,
  
  titleText = "Direct Access to Me",
  titleColor = "#1e293b",
  subtitleText = "Personalized guidance & strategy",
  subtitleColor = "#64748b",
  
  accentColor = "#3b82f6",
  arrowColor = "#3b82f6",
}) => {
  // Load Google Fonts
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // -- Animation Configuration --

  // 1. Icon Pop In
  const iconEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 12, stiffness: 100, mass: 0.8 },
  });
  const iconScale = interpolate(iconEntrance, [0, 1], [0, 1]);
  const iconOpacity = interpolate(iconEntrance, [0, 1], [0, 1]);

  // 2. Title Slide Up
  const titleEntrance = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const titleY = interpolate(titleEntrance, [0, 1], [60, 0]);
  const titleOpacity = interpolate(titleEntrance, [0, 1], [0, 1]);

  // 3. Subtitle Slide Up
  const subtitleEntrance = spring({
    frame: frame - 20,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const subtitleY = interpolate(subtitleEntrance, [0, 1], [40, 0]);
  const subtitleOpacity = interpolate(subtitleEntrance, [0, 1], [0, 1]);

  // 4. Arrow Bounce (Smooth Mixin)
  const arrowStartFrame = 45;
  const arrowEntrance = spring({
    frame: frame - arrowStartFrame,
    fps,
    config: { damping: 15, stiffness: 80 },
  });
  
  // Continuous sine wave
  const sineWave = Math.sin((frame - arrowStartFrame) / 8) * 10;
  
  // Base position slide: -20px -> 0px
  const arrowSlideY = interpolate(arrowEntrance, [0, 1], [-20, 0]);
  
  // Mix in the bounce: 0 amplitude -> Full amplitude based on entrance
  // This prevents the "jump" because when arrowEntrance is 0, the sine component is 0
  const arrowY = arrowSlideY + (sineWave * arrowEntrance);
  
  const arrowOpacity = interpolate(arrowEntrance, [0, 1], [0, 1]);

  // Responsive scaling
  const minDimension = Math.min(width, height);
  const iconSize = minDimension * 0.18; // ~194px on 1080p
  const titleSize = minDimension * 0.09; // ~97px on 1080p
  const subtitleSize = minDimension * 0.04; // ~43px on 1080p
  const arrowSize = minDimension * 0.06; // ~64px on 1080p

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Inter, sans-serif",
        transition: "none",
      }}
    >
      {/* Central Content Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
          gap: minDimension * 0.03, // Responsive gap
          flex: 1, // Push arrow to bottom area
          paddingTop: minDimension * 0.08,
          width: "100%",
        }}
      >
        {/* Animated Icon */}
        <div
          style={{
            width: iconSize,
            height: iconSize,
            borderRadius: "50%",
            backgroundColor: `${accentColor}15`, // 15% opacity tint
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: iconSize * 0.2,
            opacity: iconOpacity,
            transform: `scale(${iconScale})`,
          }}
        >
          <UserIcon color={accentColor} />
        </div>

        {/* Text Block */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: minDimension * 0.015, width: "100%" }}>
          <h1
            style={{
              fontSize: titleSize,
              fontWeight: 800,
              color: titleColor,
              margin: 0,
              letterSpacing: "-0.04em",
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              lineHeight: 1.0,
              width: "90%",
            }}
          >
            {titleText}
          </h1>
          
          <h2
            style={{
              fontSize: subtitleSize,
              fontWeight: 500,
              color: subtitleColor,
              margin: 0,
              opacity: subtitleOpacity,
              transform: `translateY(${subtitleY}px)`,
              maxWidth: "80%",
            }}
          >
            {subtitleText}
          </h2>
        </div>
      </div>

      {/* Footer / Call to Action Arrow */}
      <div
        style={{
          height: minDimension * 0.15,
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "center",
          opacity: arrowOpacity,
          transform: `translateY(${arrowY}px)`,
          width: "100%",
        }}
      >
        <div style={{ width: arrowSize, height: arrowSize }}>
          <ArrowDownIcon color={arrowColor} />
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default OneOnOneCall;